package com.posthog.hoglake.api

import com.posthog.hoglake.model.CompactionResult
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import java.io.File
import kotlin.reflect.full.memberProperties

/**
 * `CompactionResult` on the WIRE, read off both sides rather than
 * restated in either.
 *
 * There are three copies of this counter set and nothing kept them in
 * step: the stored model (`CompactionResult`, which the maintenance run
 * ledger serializes), the response DTO (`CompactionResultDto`, which
 * `POST /maintenance/compaction` returns), and the OpenAPI schema. When
 * `claimed_elsewhere` was added, the model and the spec got it and the
 * DTO did not — so the endpoint declared a field it could never emit,
 * and the only thing that would have noticed was a client generated
 * from the spec.
 *
 * The DTO's property list comes from REFLECTION and the spec's from
 * parsing the file, so neither side is a literal here. A literal would
 * have been a fourth copy.
 *
 * Unit, not integration: no database, no container — just two artifacts
 * on disk and the classes they describe.
 */
class CompactionResultSpecParityTest {
    private val spec: String = File("src/main/resources/openapi/hoglake.yaml").readText()

    /** snake_case, the wire's spelling, for a Kotlin property name. */
    private fun wire(name: String): String = name.replace(Regex("([a-z0-9])([A-Z])"), "$1_$2").lowercase()

    private fun schemaBlock(header: String): String {
        val start = spec.indexOf(header)
        assertThat(start).describedAs("spec block %s", header).isNotEqualTo(-1)
        val rest = spec.substring(start + header.length)
        val end = Regex("\n    [A-Za-z]").find(rest)?.range?.first ?: rest.length
        return rest.substring(0, end)
    }

    /** The schema's own property keys, at its indentation. */
    private fun properties(block: String): List<String> =
        Regex("""(?m)^        ([a-z_0-9]+):""").findAll(block).map { it.groupValues[1] }.toList()

    private fun requiredOf(block: String): List<String> {
        val match = Regex("""required: \[([^]]*)]""", RegexOption.DOT_MATCHES_ALL).find(block)
        assertThat(match).describedAs("CompactionResult has no `required:` list").isNotNull()
        return match!!.groupValues[1].split(",").map { it.trim() }.filter { it.isNotEmpty() }
    }

    @Test
    fun `the response DTO and the spec declare exactly the same counters`() {
        val dto = CompactionResultDto::class.memberProperties.map { wire(it.name) }.sorted()
        val declared = properties(schemaBlock("    CompactionResult:")).sorted()
        assertThat(dto)
            .describedAs(
                "every property the spec declares must exist on the DTO that answers the " +
                    "endpoint, and vice versa — a spec-only field is one no client can ever " +
                    "receive",
            )
            .isEqualTo(declared)
    }

    @Test
    fun `the stored model and the response DTO carry the same counters`() {
        // The ledger's model and the endpoint's DTO are converted one to
        // the other by hand (`CompactionResult.toDto()`), so a counter
        // can be added to the model, stored in the ledger, and never
        // reach the endpoint. That is exactly what happened.
        val model = CompactionResult::class.memberProperties.map { wire(it.name) }.sorted()
        val dto = CompactionResultDto::class.memberProperties.map { wire(it.name) }.sorted()
        assertThat(dto).isEqualTo(model)
    }

    @Test
    fun `toDto copies every counter, with no field left at its default`() {
        // `isEqualTo` on the name lists above cannot see a `toDto` that
        // maps a field to the WRONG source, or forgets one and lets the
        // data class default cover for it. Distinct values per field
        // make either visible.
        val result =
            CompactionResult(
                groupsCompacted = 1,
                filesIn = 2,
                filesOut = 3,
                bytesIn = 4,
                bytesOut = 5,
                skippedConflicts = 6,
                dvSuperseded = 7,
                unconvertibleSchema = 8,
                invalidData = 9,
                heapBudgetExceeded = 10,
                failedGroups = 11,
                claimedElsewhere = 12,
                candidatesFetched = 13,
                bucketsConsidered = 14,
                bucketsAvailable = 15,
                candidatesTruncated = 16,
                planMs = 17,
                runsTrusted = 18,
                runsSpilled = 19,
                runsDemoted = 20,
                spillBytes = 21,
                spillBudgetExceeded = 22,
                mergeBudgetExceeded = 23,
                spillCleanupFailures = 24,
                filesVerified = 25,
                filesUnsorted = 26,
                filesUnchecked = 27,
                rowGroupsAppended = 28,
                bytesAppended = 29,
                groupsRetired = 30,
                filesUnranged = 31,
                bucketsSkippedClaimed = 32,
                objectPrefixUnresolvable = 33,
                layoutProbeOnly = 34,
            )
        val dto = result.toDto()
        assertThat(dto.groupsCompacted).isEqualTo(1)
        assertThat(dto.filesIn).isEqualTo(2)
        assertThat(dto.filesOut).isEqualTo(3)
        assertThat(dto.bytesIn).isEqualTo(4)
        assertThat(dto.bytesOut).isEqualTo(5)
        assertThat(dto.skippedConflicts).isEqualTo(6)
        assertThat(dto.dvSuperseded).isEqualTo(7)
        assertThat(dto.unconvertibleSchema).isEqualTo(8)
        assertThat(dto.invalidData).isEqualTo(9)
        assertThat(dto.heapBudgetExceeded).isEqualTo(10)
        assertThat(dto.failedGroups).isEqualTo(11)
        assertThat(dto.claimedElsewhere)
            .describedAs("the counter whose absence made the endpoint unable to report it")
            .isEqualTo(12)
        // The five PLAN measures. Distinct values for the same reason
        // the counters have them: the name-equality tests above cannot
        // see `candidatesFetched = bucketsConsidered`, and this is the
        // test that exists to.
        assertThat(dto.candidatesFetched).isEqualTo(13)
        assertThat(dto.bucketsConsidered).isEqualTo(14)
        assertThat(dto.bucketsAvailable).isEqualTo(15)
        assertThat(dto.candidatesTruncated).isEqualTo(16)
        assertThat(dto.planMs).isEqualTo(17)
        // The external merge sort's counters (hoglake#134).
        assertThat(dto.runsTrusted).isEqualTo(18)
        assertThat(dto.runsSpilled).isEqualTo(19)
        assertThat(dto.runsDemoted).isEqualTo(20)
        assertThat(dto.spillBytes).isEqualTo(21)
        assertThat(dto.spillBudgetExceeded).isEqualTo(22)
        assertThat(dto.mergeBudgetExceeded).isEqualTo(23)
        assertThat(dto.spillCleanupFailures).isEqualTo(24)
        // The sortedness pre-pass's verdicts.
        assertThat(dto.filesVerified).isEqualTo(25)
        assertThat(dto.filesUnsorted).isEqualTo(26)
        assertThat(dto.filesUnchecked).isEqualTo(27)
        // Row groups appended byte for byte (package D1).
        assertThat(dto.rowGroupsAppended).isEqualTo(28)
        assertThat(dto.bytesAppended).isEqualTo(29)
        // Retired zero-survivor groups, and runs whose unknown first-key
        // range blocked an append.
        assertThat(dto.groupsRetired).isEqualTo(30)
        assertThat(dto.filesUnranged).isEqualTo(31)
        // The pre-probe bucket-claim skips: a plan measure beside
        // bucketsConsidered, so a `toDto` that copied one into the other
        // is exactly what the distinct value catches.
        assertThat(dto.bucketsSkippedClaimed).isEqualTo(32)
        // The object-prefix planner refusal (2.1d), a group counter beside
        // the budget refusals.
        assertThat(dto.objectPrefixUnresolvable).isEqualTo(33)
        // The variant-layout probe that found nothing to rewrite: an
        // attempt with no rewrite, beside the other charged skips.
        assertThat(dto.layoutProbeOnly).isEqualTo(34)
    }

    @Test
    fun `claimed_elsewhere is optional on the wire, like every counter added after the ledger`() {
        // NON_DEFAULT on the stored model means a zero is omitted from a
        // ledger row, and rows older than the counter never had it at
        // all — so `required` would be a promise the ledger's own
        // history breaks. The read path fills 0, which is why absence
        // reads as zero rather than as unknown.
        val block = schemaBlock("    CompactionResult:")
        assertThat(properties(block)).contains("claimed_elsewhere")
        assertThat(requiredOf(block))
            .describedAs("a required counter cannot be one the ledger has rows without")
            .doesNotContain("claimed_elsewhere")
    }

    @Test
    fun `the external merge sort's counters are optional, and heap_budget_exceeded stays required`() {
        // Added after the ledger started recording, so optional for the
        // claimed_elsewhere reason. heap_budget_exceeded is the opposite
        // case: nothing produces it any more, but it was REQUIRED on the
        // wire before, and dropping it — or making it optional — would
        // break a client generated from the old spec. It stays, reads 0,
        // and says it is historical.
        val block = schemaBlock("    CompactionResult:")
        val added =
            listOf(
                "runs_trusted",
                "runs_spilled",
                "runs_demoted",
                "spill_bytes",
                "spill_budget_exceeded",
                "merge_budget_exceeded",
                "spill_cleanup_failures",
                "files_verified",
                "files_unsorted",
                "files_unchecked",
                "row_groups_appended",
                "bytes_appended",
                // Not merge-sort counters, but added after the ledger by
                // the same rule: retired zero-survivor groups, and runs
                // whose unknown range blocked an append.
                "groups_retired",
                "files_unranged",
                // The pre-probe bucket-claim skips, added after the
                // ledger like every counter in this list.
                "buckets_skipped_claimed",
                // The object-prefix planner refusal (2.1d).
                "object_prefix_unresolvable",
                // The variant-layout probe that found nothing to rewrite.
                "layout_probe_only",
            )
        assertThat(properties(block)).containsAll(added)
        assertThat(requiredOf(block)).doesNotContainAnyElementsOf(added)
        assertThat(requiredOf(block)).contains("heap_budget_exceeded")
        val heap = block.substringAfter("        heap_budget_exceeded:").substringBefore("\n        failed_groups:")
        assertThat(heap).describedAs("the spec must say the counter is historical").containsIgnoringCase("historical")
    }
}

package com.posthog.hoglake.api

import com.posthog.hoglake.model.StorageUsage
import com.posthog.hoglake.wireObjectMapper
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import java.io.File

class StorageUsageSpecParityTest {
    @Test
    fun `footprint wire uses required decimal strings without precision loss`() {
        val spec = File("src/main/resources/openapi/hoglake.yaml").readText()
        val block = spec.substringAfter("    StorageUsage:\n").substringBefore("\n    Catalog:\n")
        val properties =
            Regex("(?m)^        ([a-z_]+):").findAll(block).map { it.groupValues[1] }.toList()
        val required =
            Regex("""required: \[([^]]*)]""").find(block)!!.groupValues[1]
                .split(",").map { it.trim() }
        val body =
            wireObjectMapper().valueToTree<com.fasterxml.jackson.databind.JsonNode>(
                StorageUsage(Long.MAX_VALUE, Long.MAX_VALUE).toDto(),
            )
        assertThat(body.fieldNames().asSequence().toList()).containsExactlyInAnyOrderElementsOf(properties)
        assertThat(properties).containsExactlyInAnyOrderElementsOf(required)
        assertThat(Regex("(?m)^          type: string$").findAll(block).count()).isEqualTo(2)
        for (field in properties) {
            assertThat(body[field].isTextual).isTrue()
            assertThat(body[field].asText()).isEqualTo("9223372036854775807")
        }
        assertThat(spec).contains("  /catalogs/{catalog}/storage-usage:")
    }
}

import "@testing-library/jest-dom/vitest";
import { cleanup } from "@testing-library/react";
import { afterEach, vi } from "vitest";
import { resetAuthForTests } from "../src/lib/auth";

// Node's experimental localStorage global (inert without
// --localstorage-file) preempts jsdom's implementation, leaving
// window.localStorage undefined under vitest. Back it with a Map.
// sessionStorage (the sign-in token's home) gets the same treatment.
function mapStorage(): Storage {
  const store = new Map<string, string>();
  return {
    getItem: (k: string) => store.get(k) ?? null,
    setItem: (k: string, v: string) => void store.set(k, String(v)),
    removeItem: (k: string) => void store.delete(k),
    clear: () => store.clear(),
    key: (i: number) => [...store.keys()][i] ?? null,
    get length() {
      return store.size;
    },
  };
}
if (typeof window !== "undefined") {
  for (const name of ["localStorage", "sessionStorage"] as const) {
    if (!window[name]) {
      Object.defineProperty(window, name, { configurable: true, value: mapStorage() });
    }
  }
}

vi.mock("uplot", async () => {
